use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " A list of flush types."] # [doc = ""] # [doc = " See <http://www.bolet.org/~pornin/deflate-flush.html> for more in-depth info."] # [repr (i32)] # [derive (Copy , Clone , PartialEq , Eq)] # [cfg_attr (not (feature = "rustc-dep-of-std") , derive (Hash , Debug))] pub enum MZFlush { # [doc = " Don't force any flushing."] # [doc = " Used when more input data is expected."] None = 0 , # [doc = " Zlib partial flush."] # [doc = " Currently treated as [`Sync`]."] Partial = 1 , # [doc = " Finish compressing the currently buffered data, and output an empty raw block."] # [doc = " Has no use in decompression."] Sync = 2 , # [doc = " Same as [`Sync`], but resets the compression dictionary so that further compressed"] # [doc = " data does not depend on data compressed before the flush."] # [doc = ""] # [doc = " Has no use in decompression, and is an error to supply in that case."] Full = 3 , # [doc = " Attempt to flush the remaining data and end the stream."] Finish = 4 , # [doc = " Not implemented."] Block = 5 , }